@using sv_12808e2e76194411a831213312d2babc.Services
@namespace sv_12808e2e76194411a831213312d2babc.Components.Pages.Chat
@rendermode InteractiveServer
@inject IChatService ChatService

<PageTitle>Team Chat</PageTitle>

<div class="chat-layout">
    <div class="chat-sidebar">
        <ChannelList Channels="_channels"
                     SelectedChannelId="_selectedChannelId"
                     OnChannelSelected="HandleChannelSelected" />
    </div>

    <div class="chat-main @(_threadOpen ? "with-thread" : "full-width")">
        <MessageArea Channel="_selectedChannel"
                     Messages="_messages"
                     ThreadReplyCounts="_threadReplyCounts"
                     OnSendMessage="HandleSendMessage"
                     OnOpenThread="HandleOpenThread"
                     OnReact="HandleReact"
                     OnLoadMore="HandleLoadMore" />
    </div>

    @if (_threadOpen)
    {
        <div class="chat-thread">
            <ThreadPanel RootMessage="_threadRootMessage"
                         Replies="_threadReplies"
                         OnClose="HandleCloseThread"
                         OnReply="HandleThreadReply" />
        </div>
    }
</div>

@code {
    private List<Channel>? _channels;
    private int _selectedChannelId;
    private Channel? _selectedChannel;
    private List<Message> _messages = [];
    private Dictionary<int, int> _threadReplyCounts = new();

    private bool _threadOpen;
    private Message? _threadRootMessage;
    private List<Message> _threadReplies = [];

    private const int PageSize = 30;

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
        if (_channels.Count > 0)
        {
            await HandleChannelSelected(_channels[0].Id);
        }
    }

    private async Task HandleChannelSelected(int channelId)
    {
        _selectedChannelId = channelId;
        _selectedChannel = _channels?.FirstOrDefault(c => c.Id == channelId);
        _messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        await ChatService.MarkChannelReadAsync(channelId);
        await ComputeThreadReplyCounts();
        _threadOpen = false;
    }

    private async Task ComputeThreadReplyCounts()
    {
        _threadReplyCounts.Clear();
        // Identify thread starters: messages that have replies (other messages with ReplyToId pointing to them)
        var rootIds = _messages
            .Where(m => m.ReplyToId is null)
            .Select(m => m.Id)
            .ToHashSet();

        foreach (var rootId in rootIds)
        {
            var thread = await ChatService.GetThreadAsync(rootId);
            if (thread.Count > 0)
            {
                _threadReplyCounts[rootId] = thread.Count;
            }
        }
    }

    private async Task HandleSendMessage(string content)
    {
        var message = await ChatService.SendMessageAsync(_selectedChannelId, content, null);
        _messages.Add(message);
    }

    private async Task HandleOpenThread(int messageId)
    {
        _threadRootMessage = _messages.FirstOrDefault(m => m.Id == messageId);
        _threadReplies = await ChatService.GetThreadAsync(messageId);
        _threadOpen = true;
    }

    private async Task HandleReact((int MessageId, string Emoji) reaction)
    {
        await ChatService.AddReactionAsync(reaction.MessageId, reaction.Emoji);
        // Refresh messages to reflect the new reaction
        _messages = await ChatService.GetMessagesAsync(_selectedChannelId, 0, _messages.Count);
    }

    private void HandleCloseThread()
    {
        _threadOpen = false;
        _threadRootMessage = null;
        _threadReplies = [];
    }

    private async Task HandleThreadReply(string content)
    {
        if (_threadRootMessage is null) return;
        var reply = await ChatService.SendMessageAsync(_selectedChannelId, content, _threadRootMessage.Id);
        _threadReplies.Add(reply);
        // Update reply count
        _threadReplyCounts[_threadRootMessage.Id] = _threadReplies.Count;
    }

    private async Task HandleLoadMore()
    {
        var olderMessages = await ChatService.GetMessagesAsync(_selectedChannelId, _messages.Count, PageSize);
        if (olderMessages.Count > 0)
        {
            _messages.InsertRange(0, olderMessages);
        }
    }
}

.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
}

.chat-sidebar {
    width: 20%;
    min-width: 200px;
    background: #2c2f33;
    color: #dcddde;
    border-right: 1px solid #202225;
    overflow-y: auto;
}

.chat-main {
    flex: 1;
    display: flex;
    flex-direction: column;
    background: #36393f;
    color: #dcddde;
}

.chat-main.with-thread {
    width: 55%;
    flex: none;
}

.chat-main.full-width {
    width: 80%;
    flex: 1;
}

.chat-thread {
    width: 25%;
    min-width: 280px;
    background: #2f3136;
    color: #dcddde;
    border-left: 1px solid #202225;
    display: flex;
    flex-direction: column;
}

.channel-list {
    padding: 12px 0;
}

.channel-list-header {
    padding: 0 16px 8px;
    font-size: 0.75rem;
    text-transform: uppercase;
    letter-spacing: 0.02em;
    color: #8e9297;
    margin: 0;
}

.channel-item {
    padding: 8px 16px;
    cursor: pointer;
    position: relative;
    transition: background 0.1s;
}

.channel-item:hover {
    background: #34373c;
}

.channel-item.active {
    background: #393c43;
    border-left: 3px solid #5865f2;
}

.channel-name {
    font-weight: 600;
    font-size: 0.95rem;
    color: #fff;
}

.channel-description {
    font-size: 0.8rem;
    color: #8e9297;
    margin-top: 2px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.unread-badge {
    position: absolute;
    right: 12px;
    top: 50%;
    transform: translateY(-50%);
    background: #ed4245;
    color: #fff;
    font-size: 0.7rem;
    font-weight: 700;
    padding: 2px 6px;
    border-radius: 10px;
    min-width: 18px;
    text-align: center;
}

.message-area {
    display: flex;
    flex-direction: column;
    height: 100%;
    overflow: hidden;
}

.message-area-header {
    padding: 12px 20px;
    border-bottom: 1px solid #202225;
    flex-shrink: 0;
}

.message-area-header h2 {
    margin: 0;
    font-size: 1.1rem;
    color: #fff;
}

.message-area-header p {
    margin: 4px 0 0;
    font-size: 0.8rem;
    color: #8e9297;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 16px 20px;
}

.loading-indicator {
    text-align: center;
    color: #8e9297;
    padding: 8px;
    font-size: 0.85rem;
}

.message-input-area {
    display: flex;
    gap: 8px;
    padding: 12px 20px;
    border-top: 1px solid #202225;
    flex-shrink: 0;
}

.message-input {
    flex: 1;
    background: #40444b;
    border: none;
    border-radius: 8px;
    padding: 10px 14px;
    color: #dcddde;
    font-size: 0.9rem;
    resize: none;
    min-height: 40px;
    max-height: 120px;
    font-family: inherit;
}

.message-input:focus {
    outline: none;
    box-shadow: 0 0 0 2px #5865f2;
}

.send-btn {
    background: #5865f2;
    color: #fff;
    border: none;
    border-radius: 8px;
    padding: 10px 20px;
    font-weight: 600;
    cursor: pointer;
    transition: background 0.15s;
    align-self: flex-end;
}

.send-btn:hover:not(:disabled) {
    background: #4752c4;
}

.send-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

.message-item {
    padding: 8px 12px;
    border-radius: 6px;
    position: relative;
    margin-bottom: 4px;
    transition: background 0.1s;
}

.message-item:hover {
    background: #32353b;
}

.message-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 2px;
}

.message-author {
    font-weight: 600;
    color: #fff;
    font-size: 0.9rem;
}

.message-time {
    font-size: 0.75rem;
    color: #72767d;
}

.message-content {
    font-size: 0.9rem;
    line-height: 1.4;
    color: #dcddde;
    word-wrap: break-word;
}

.message-reactions {
    display: flex;
    gap: 4px;
    margin-top: 4px;
    flex-wrap: wrap;
}

.reaction-badge {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    background: #2f3136;
    border: 1px solid #40444b;
    border-radius: 4px;
    padding: 2px 8px;
    font-size: 0.8rem;
    cursor: pointer;
    transition: border-color 0.15s;
}

.reaction-badge:hover {
    border-color: #5865f2;
}

.thread-link {
    background: none;
    border: none;
    color: #5865f2;
    font-size: 0.8rem;
    font-weight: 600;
    cursor: pointer;
    padding: 4px 0;
    margin-top: 4px;
}

.thread-link:hover {
    text-decoration: underline;
}

.message-actions {
    position: absolute;
